const $ = (selector, scope = document) => scope.querySelector(selector);
const $$ = (selector, scope = document) => [...scope.querySelectorAll(selector)];
const languageTrigger = $(".language-trigger");
const languagePanel = $("#language-panel");
const menuTrigger = $(".menu-trigger");
const siteMenu = $("#site-menu");
const heroVideo = $(".hero-video");
let activeLanguage = new URLSearchParams(location.search).get("lang") || localStorage.getItem("sunnylnn-language") || "en";
if (!translations[activeLanguage]) activeLanguage = "en";

function updateInternalLinks(lang) {
  $$('a[href]').forEach(link => {
    const raw = link.getAttribute('href');
    if (!raw || raw.startsWith('#') || raw.startsWith('http') || raw.startsWith('mailto:')) return;
    const url = new URL(raw, location.href);
    url.searchParams.set('lang', lang);
    link.setAttribute('href', `${url.pathname.split('/').pop() || 'index.html'}?${url.searchParams.toString()}${url.hash}`);
  });
}

function setLanguage(lang) {
  activeLanguage = lang;
  localStorage.setItem("sunnylnn-language", lang);
  document.documentElement.lang = lang === "zh" ? "zh-CN" : lang;
  languageTrigger.textContent = lang.toUpperCase();
  $$('[data-i18n]').forEach(node => {
    const value = translations[lang][node.dataset.i18n] || translations.en[node.dataset.i18n];
    if (value) node.textContent = value;
  });
  $$('[data-language]').forEach(button => button.classList.toggle('active', button.dataset.language === lang));
  const url = new URL(location.href);
  url.searchParams.set('lang', lang);
  history.replaceState({}, '', url);
  updateInternalLinks(lang);
  updateDateSelectors(lang);
}

function updateDateSelectors(lang = activeLanguage) {
  const locale = lang === 'zh' ? 'zh-CN' : lang === 'en' ? 'en-GB' : lang;
  const monthFormatter = new Intl.DateTimeFormat(locale, { month: 'long', timeZone: 'UTC' });
  $$('[data-date-select]').forEach(group => {
    const day = $('[data-date-part="day"]', group);
    const month = $('[data-date-part="month"]', group);
    const year = $('[data-date-part="year"]', group);
    const hidden = $('input[type="hidden"]', group);
    if (!day || !month || !year || !hidden) return;

    const selectedDay = day.value;
    const selectedMonth = month.value;
    const selectedYear = year.value;
    const currentYear = new Date().getFullYear();
    day.innerHTML = `<option value="">${lang === 'zh' ? '日' : 'DD'}</option>${Array.from({ length: 31 }, (_, index) => `<option value="${String(index + 1).padStart(2, '0')}">${index + 1}</option>`).join('')}`;
    month.innerHTML = `<option value="">${lang === 'zh' ? '月' : lang === 'en' ? 'Month' : '—'}</option>${Array.from({ length: 12 }, (_, index) => `<option value="${String(index + 1).padStart(2, '0')}">${monthFormatter.format(new Date(Date.UTC(2026, index, 1)))}</option>`).join('')}`;
    year.innerHTML = `<option value="">${lang === 'zh' ? '年' : 'YYYY'}</option>${Array.from({ length: 6 }, (_, index) => `<option value="${currentYear + index}">${currentYear + index}</option>`).join('')}`;
    day.value = selectedDay;
    month.value = selectedMonth;
    year.value = selectedYear;

    const sync = () => {
      hidden.value = day.value && month.value && year.value ? `${year.value}-${month.value}-${day.value}` : '';
    };
    if (!group.dataset.dateReady) {
      [day, month, year].forEach(select => select.addEventListener('change', sync));
      group.dataset.dateReady = 'true';
    }
    sync();
  });
}

function closeLanguage() {
  languagePanel?.classList.remove('open');
  languagePanel?.setAttribute('aria-hidden', 'true');
  languageTrigger?.setAttribute('aria-expanded', 'false');
  document.body.classList.remove('language-open');
}

function closeMenu() {
  siteMenu?.classList.remove('open');
  siteMenu?.setAttribute('aria-hidden', 'true');
  menuTrigger?.setAttribute('aria-expanded', 'false');
  menuTrigger?.classList.remove('is-open');
  document.body.classList.remove('menu-open');
  if (heroVideo && !matchMedia('(prefers-reduced-motion: reduce)').matches) heroVideo.play().catch(() => {});
}

languageTrigger?.addEventListener('click', () => {
  const willOpen = !languagePanel.classList.contains('open');
  closeMenu();
  languagePanel.classList.toggle('open', willOpen);
  languagePanel.setAttribute('aria-hidden', String(!willOpen));
  languageTrigger.setAttribute('aria-expanded', String(willOpen));
  document.body.classList.toggle('language-open', willOpen);
});

menuTrigger?.addEventListener('click', () => {
  const willOpen = !siteMenu.classList.contains('open');
  closeLanguage();
  siteMenu.classList.toggle('open', willOpen);
  siteMenu.setAttribute('aria-hidden', String(!willOpen));
  menuTrigger.setAttribute('aria-expanded', String(willOpen));
  menuTrigger.classList.toggle('is-open', willOpen);
  document.body.classList.toggle('menu-open', willOpen);
  if (heroVideo) willOpen ? heroVideo.pause() : heroVideo.play().catch(() => {});
});

$$('[data-language]').forEach(button => button.addEventListener('click', () => { setLanguage(button.dataset.language); closeLanguage(); }));
document.addEventListener('keydown', event => { if (event.key === 'Escape') { closeLanguage(); closeMenu(); } });
document.addEventListener('click', event => { if (languagePanel?.classList.contains('open') && !languagePanel.contains(event.target) && !languageTrigger.contains(event.target)) closeLanguage(); });

const header = $('#site-header') || $('.site-header');
function updateHeader() { if (!header?.classList.contains('solid')) header?.classList.toggle('scrolled', scrollY > 40); }
addEventListener('scroll', updateHeader, { passive: true });
updateHeader();

const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target); } }), { threshold: .12 });
$$('.reveal').forEach(node => observer.observe(node));

const listingSort = $('#listing-sort');
const listingGrid = $('#listing-grid');
listingSort?.addEventListener('change', () => {
  const cards = $$('.collection-card', listingGrid);
  cards.sort((a, b) => {
    if (listingSort.value === 'az') return a.dataset.title.localeCompare(b.dataset.title, activeLanguage);
    if (listingSort.value === 'za') return b.dataset.title.localeCompare(a.dataset.title, activeLanguage);
    return Number(a.dataset.order) - Number(b.dataset.order);
  });
  listingGrid.append(...cards);
});

const galleryDialog = $('#gallery-dialog');
const galleryDialogImage = $('#gallery-dialog-image');
const galleryDialogCaption = $('#gallery-dialog-caption');
const propertyPhotos = $$('.property-photo img');
let activePhotoIndex = 0;

function showPropertyPhoto(index) {
  if (!propertyPhotos.length || !galleryDialogImage) return;
  activePhotoIndex = (index + propertyPhotos.length) % propertyPhotos.length;
  const source = propertyPhotos[activePhotoIndex];
  galleryDialogImage.src = source.currentSrc || source.src;
  galleryDialogImage.alt = source.alt;
  galleryDialogCaption.textContent = `${String(activePhotoIndex + 1).padStart(2, '0')} / ${String(propertyPhotos.length).padStart(2, '0')}`;
}

$$('.property-photo').forEach(photo => {
  $('.gallery-open', photo)?.addEventListener('click', () => {
    showPropertyPhoto(Number(photo.dataset.galleryIndex || 0));
    galleryDialog?.showModal();
  });
});

$('.gallery-close')?.addEventListener('click', () => galleryDialog?.close());
$('.gallery-previous')?.addEventListener('click', () => showPropertyPhoto(activePhotoIndex - 1));
$('.gallery-next')?.addEventListener('click', () => showPropertyPhoto(activePhotoIndex + 1));
galleryDialog?.addEventListener('click', event => { if (event.target === galleryDialog) galleryDialog.close(); });
galleryDialog?.addEventListener('keydown', event => {
  if (event.key === 'ArrowLeft') showPropertyPhoto(activePhotoIndex - 1);
  if (event.key === 'ArrowRight') showPropertyPhoto(activePhotoIndex + 1);
});

const contactForm = $('#contact-form');
const enquiryTabs = $$('.enquiry-tab');
const bookingFields = $('#booking-fields');
const ownerFields = $('#owner-fields');
const bookingGuidance = $('.booking-guidance');
const ownerGuidance = $('.owner-guidance');
const inquiryType = $('#inquiry-type');
const inquirySubject = $('#inquiry-subject');
const inquiryLanguage = $('#inquiry-language');
const inquiryPageUrl = $('#inquiry-page-url');
const submitLabel = $('.submit-label');
const formStatus = $('.form-status');

function translated(key) {
  return translations[activeLanguage]?.[key] || translations.en[key] || key;
}

function setFormStatus(message = '', state = '') {
  if (!formStatus) return;
  formStatus.textContent = message;
  if (state) formStatus.dataset.state = state;
  else delete formStatus.dataset.state;
}

function setEnquiryType(type, updateUrl = true) {
  if (!contactForm) return;
  const owner = type === 'owner';
  enquiryTabs.forEach(tab => {
    const active = tab.dataset.enquiryType === type;
    tab.classList.toggle('active', active);
    tab.setAttribute('aria-selected', String(active));
    tab.tabIndex = active ? 0 : -1;
  });
  bookingFields.hidden = owner;
  bookingFields.disabled = owner;
  ownerFields.hidden = !owner;
  ownerFields.disabled = !owner;
  if (bookingGuidance) bookingGuidance.hidden = owner;
  if (ownerGuidance) ownerGuidance.hidden = !owner;
  inquiryType.value = owner ? 'Property management enquiry' : 'Booking enquiry';
  inquirySubject.value = owner ? 'New Sunnylnn property management enquiry' : 'New Sunnylnn booking enquiry';
  const labelKey = owner ? 'form.sendOwner' : 'form.sendBooking';
  submitLabel.dataset.i18n = labelKey;
  submitLabel.textContent = translated(labelKey);
  setFormStatus();
  if (updateUrl) {
    const url = new URL(location.href);
    url.searchParams.set('type', type);
    history.replaceState({}, '', url);
  }
}

enquiryTabs.forEach((tab, index) => {
  tab.addEventListener('click', () => setEnquiryType(tab.dataset.enquiryType));
  tab.addEventListener('keydown', event => {
    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
    event.preventDefault();
    const next = enquiryTabs[(index + (event.key === 'ArrowRight' ? 1 : -1) + enquiryTabs.length) % enquiryTabs.length];
    next.focus();
    setEnquiryType(next.dataset.enquiryType);
  });
});

if (contactForm) {
  const params = new URLSearchParams(location.search);
  setEnquiryType(params.get('type') === 'owner' ? 'owner' : 'booking', false);
  const residenceNames = {
    'glacier': 'Glacier', 'the-tower': 'The Tower', 'boxwood-gardens': 'Boxwood Gardens',
    'bankside-tower': 'Bankside Tower', 'merino-gardens': 'Merino Gardens', 'neroli': 'Neroli',
    'penthouse-wharf': 'Penthouse Wharf', 'queens-gate': 'Queens Gate'
  };
  const requestedResidence = params.get('residence') || residenceNames[params.get('listing')];
  const residenceSelect = $('[name="residence"]', contactForm);
  if (requestedResidence && residenceSelect && [...residenceSelect.options].some(option => option.value === requestedResidence)) residenceSelect.value = requestedResidence;
  inquiryLanguage.value = activeLanguage;
  inquiryPageUrl.value = location.href;

  contactForm.addEventListener('submit', async event => {
    event.preventDefault();
    if (!contactForm.checkValidity()) {
      contactForm.reportValidity();
      setFormStatus(translated('form.required'), 'error');
      return;
    }

    const endpoint = contactForm.dataset.formspreeEndpoint?.trim();
    if (!endpoint) {
      setFormStatus(translated('form.setup'), 'error');
      return;
    }

    const submitButton = $('button[type="submit"]', contactForm);
    submitButton.disabled = true;
    submitButton.setAttribute('aria-busy', 'true');
    setFormStatus(translated('form.sending'));
    inquiryLanguage.value = activeLanguage;
    inquiryPageUrl.value = location.href;

    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        body: new FormData(contactForm),
        headers: { Accept: 'application/json' }
      });
      if (!response.ok) throw new Error(`Submission failed with ${response.status}`);
      const selectedType = inquiryType.value === 'Property management enquiry' ? 'owner' : 'booking';
      contactForm.reset();
      setEnquiryType(selectedType, false);
      setFormStatus(translated('form.success'), 'success');
    } catch (error) {
      setFormStatus(translated('form.error'), 'error');
    } finally {
      submitButton.disabled = false;
      submitButton.removeAttribute('aria-busy');
    }
  });
}

if ($('#year')) $('#year').textContent = new Date().getFullYear();
setLanguage(activeLanguage);
